  width: 100%;
  max-width: 360px;
  display: flex;
  flex-direction: column;
  gap: var(--g-spacing-4);
  padding: var(--g-spacing-7);
  background: var(--g-color-base-float);
  border-radius: var(--g-border-radius-l);
  box-shadow: var(--g-shadow-l);
}

